/* ============================================================
   Ai Way Browser Harness — single-file, local-first architecture
   Core State / Storage / Sessions / Workspace / RepositoryMap /
   Rules / Skills / Memory / ContextManager / TokenBudget /
   Compaction / Tools / ToolPolicy / Checkpoints / ModelAdapter /
   Agent / Markdown / Editor / UI
   ============================================================ */

/* ========================= Core ========================= */
const Core=(()=>{
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
  const uid=()=>`${Date.now().toString(36)}${Math.random().toString(36).slice(2,9)}`;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
  const debounce=(fn,ms)=>{let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms)}};
  const trunc=(s,n=4000)=>{s=String(s??'');return s.length>n?s.slice(0,n)+`\n…[truncated ${s.length-n} chars]`:s};
  const lineCount=s=>String(s??'').split('\n').length;
  const baseName=p=>String(p||'').split('/').pop();
  const dirName=p=>String(p||'').includes('/')?String(p).slice(0,String(p).lastIndexOf('/')):'';
  const extOf=p=>{const b=baseName(p),i=b.lastIndexOf('.');return i>0?b.slice(i+1).toLowerCase():''};
  const fmtDate=ts=>new Date(ts||Date.now()).toLocaleString('ar-EG-u-nu-latn',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
  const fmtDur=ms=>ms<1000?`${ms}ms`:`${(ms/1000).toFixed(1)}ث`;
  const fmtNum=n=>Number(n||0).toLocaleString('en-US');
  const estimateTokens=s=>Math.max(1,Math.ceil(String(s??'').length/3.6));
  const idle=fn=>(window.requestIdleCallback||((cb)=>setTimeout(cb,40)))(fn);
  const safeJson=s=>{try{return JSON.parse(s)}catch{return null}};
  const normalizePath=p=>{
    if(typeof p!=='string') return null;
    p=p.trim().replace(/\\/g,'/').replace(/^(\.\/)+/,'').replace(/^\/+/, '').replace(/\/{2,}/g,'/').replace(/\/+$/,'');
    if(!p||p.length>400) return null;
    const segs=p.split('/');
    if(segs.some(s=>!s||s==='.'||s==='..')||/[<>:"|?*\x00-\x1f]/.test(p)) return null;
    return p;
  };
  const assertPath=p=>{const n=normalizePath(p);if(!n) throw new Error(`مسار غير صالح: ${String(p)}`);return n};
  const redact=s=>String(s??'').replace(/(sk-[A-Za-z0-9_\-]{12,}|tvly-[A-Za-z0-9_\-]{10,}|Bearer\s+[A-Za-z0-9._\-]{10,})/gi,'[REDACTED]');
  return {$,$$,uid,esc,sleep,clamp,debounce,trunc,lineCount,baseName,dirName,extOf,fmtDate,fmtDur,fmtNum,estimateTokens,idle,safeJson,normalizePath,assertPath,redact};
})();
const {$,$$,uid,esc,sleep,clamp,debounce,trunc,lineCount,baseName,dirName,extOf,fmtDate,fmtDur,fmtNum,estimateTokens,idle,safeJson,normalizePath,assertPath,redact}=Core;

